// Package gitlog reads commit messages from a local repository.
package gitlog

import (
	"context"
	"fmt"
	"os/exec"
	"strconv"
	"strings"
)

type Commit struct {
	SHA     string
	Message string
}

// Subject returns the first line of the commit message.
func (c Commit) Subject() string {
	s, _, _ := strings.Cut(c.Message, "\n")
	return s
}

// Log returns up to max commits in revRange (e.g. "main..HEAD" or "HEAD~20..HEAD";
// empty means the current branch). Merge commits are skipped since their
// messages are usually generated by git itself.
func Log(ctx context.Context, repo, revRange string, max int) ([]Commit, error) {
	args := []string{"-C", repo, "log", "--no-merges", "--format=%H%x1f%B%x1e", "-n", strconv.Itoa(max)}
	if revRange != "" {
		if strings.HasPrefix(revRange, "-") {
			return nil, fmt.Errorf("invalid revision range %q", revRange)
		}
		args = append(args, revRange)
	}
	args = append(args, "--")
	out, err := exec.CommandContext(ctx, "git", args...).Output()
	if err != nil {
		if ee, ok := err.(*exec.ExitError); ok {
			return nil, fmt.Errorf("git log: %s", strings.TrimSpace(string(ee.Stderr)))
		}
		return nil, fmt.Errorf("git log: %w", err)
	}
	var commits []Commit
	for _, rec := range strings.Split(string(out), "\x1e") {
		sha, msg, ok := strings.Cut(strings.TrimSpace(rec), "\x1f")
		if !ok {
			continue
		}
		commits = append(commits, Commit{SHA: sha, Message: strings.TrimSpace(msg)})
	}
	return commits, nil
}
